/** Генератор случайных чисел в [0, 1). */
export interface Rng {
  next(): number;
}

/** Ответ раунда — одинаковый у HTTP API и testkit. */
export interface RoundView {
  roundId: string;
  gameId: string;
  bet: number;
  status: 'open' | 'closed';
  view: any;
  payout: number | null;
  balance: number;
}

